/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/spin/style/index.less';
import { Spin } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    state = {
        loading: true
    }

    click = () => {
        this.setState({
            loading:!this.state.loading,
        })
    }

    render() {
        return (
            <div style={{ margin: 10 }}>
                <div style={{ margin: 10 }}>
                    <Spin />
                </div>
                <div style={{ margin: 10 }}>
                    <Spin block />
                </div>
                <div style={{ margin: 10 }}>
                    <Spin size="large" block />
                </div>
                <div style={{display:"flex"}}>
                    <Spin size="small" loading={this.state.loading}>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                    <Spin loading={this.state.loading}>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                    <Spin size="large" loading={this.state.loading}>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                </div>

                <div style={{display:"flex"}}>
                    <Spin size="small" loading={this.state.loading} block>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                    <Spin loading={this.state.loading} block>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                    <Spin size="large" loading={this.state.loading} block>
                        <div style={{width:200}}>123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                        <div >123</div>
                    </Spin>
                </div>
                
                
                <button onClick={() => this.click()}>load</button>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



